/* V3: 36 deliberately composed screens. Shared facts/actions, NOT a shared page template. */
window.LWPages = (() => {
  const ready = (c) => {
    const {state,badge,running,stale} = c;
    const runs = state.runs.filter(r => r.id !== 'DEMO-RUN-01' || running() || state.hasCompletedDemo);
    const current = state.scenarioStatus;
    const scenarios = c.scenarios.filter(s => (current === 'all' || s.status === current) && `${s.id} ${s.name} ${s.purpose} ${s.tags.join(' ')}`.toLowerCase().includes(state.scenarioQuery.toLowerCase()));
    const filteredRuns = runs.filter(r => (state.runStatus === 'all' || r.result === state.runStatus) && `${r.id} ${r.title} ${r.target}`.toLowerCase().includes(state.runQuery.toLowerCase()));
    return {runs,scenarios,filteredRuns,queue:state.queue,active:running(),badge,stale:stale()};
  };
  const link = (text,where) => `<button class="link-button" type="button" data-nav="${where}">${text} ↗</button>`;
  const openRun = (id,text='查看详情') => `<button class="link-button" type="button" data-run="${id}">${text} ↗</button>`;
  const btn = (c,text,attrs='',primary=false) => c.action(text,attrs,primary);
  const wrapper = (view,style,html) => `<div class="view v3-view v3-${view} v3-${style}">${html}</div>`;
  const eyebrow = text => `<span class="micro">${text}</span>`;
  const intro = (c,kicker,title,desc,tools='') => `<header class="v3-intro">${eyebrow(kicker)}<div class="v3-intro-row"><div><h1>${title}</h1><p>${desc}</p></div>${tools?`<div class="row wrap">${tools}</div>`:''}</div></header>`;
  const idle = (c) => `<div class="v3-idle-note">${eyebrow('CURRENT / IDLE')}<strong>当前没有正在执行的测试</strong><p>看待测变化、最近结果与需要处理的事项；不把空闲伪装为进度 0/4。</p></div>`;
  const activeSummary = c => c.running() ? `<div class="v3-active-summary"><span class="dot"></span><strong>Runner 正在执行</strong><span>DEMO-RUN-01 · 用户会话恢复 · ${c.progress()}</span>${link('打开详情','active')}</div>` : '';
  const lastResult = c => `<div class="v3-last"><span class="micro">最近已完成</span><strong>DEMO-RUN-00 <span class="tag good">passed</span></strong><small>核心业务回归 · target 示例提交 B · 报告已归档</small>${openRun('DEMO-RUN-00','查看报告')}</div>`;
  const tasks = c => [
    c.running()?['01','正在测试','示例提交 A 已固定为 DEMO-RUN-01 的目标；结论尚待审核。',`data-nav="active"`,'查看执行']:['01','待测变化','示例提交 A 已进入场景测试分支，尚未成为已完成测试目标。',`data-nav="git"`,'查看提交'],
    ['02','归档需重试','DEMO-RUN-ARCHIVE 的测试结论已成立，但归档未完成。',`data-run="DEMO-RUN-ARCHIVE"`,'查看 Run'],
    ['03','场景草稿','资料保存与回读仍处于 draft，查看预期与历史。',`data-nav="scenarios"`,'查看场景']
  ];
  const activities = c => [
    ['分支更新','场景测试分支纳入示例提交 A','待测变更'],
    ['报告归档','DEMO-RUN-00 的正式报告已索引','历史事实'],
    ['Run 结束','DEMO-RUN-XX 因依赖阻塞，未推进目标','blocked']
  ];
  const taskRows = c => tasks(c).map(([n,title,desc,attr,verb])=>`<article class="v3-task"><span class="v3-index">${n}</span><div><h3>${title}</h3><p>${desc}</p></div><button class="link-button" type="button" ${attr}>${verb} ↗</button></article>`).join('');
  const activityRows = c => activities(c).map(([title,desc,kind],i)=>`<div class="v3-activity"><span class="v3-index">${String(i+1).padStart(2,'0')}</span><div><strong>${title}</strong><p>${desc}</p></div><span class="fine">${kind}</span></div>`).join('');
  const queue = c => c.state.queue.length ? c.state.queue.map(q=>`<div class="v3-queue-row"><b>${c.escape(q.id)}</b><span>${c.escape(q.source)}</span>${c.badge(q.status)}</div>`).join('') : `<div class="v3-empty-queue"><strong>队列为空</strong><span>有新请求时会按 FIFO 顺序进入执行。</span></div>`;
  const summaryFacts = c => `<div class="v3-facts"><div><span>${c.running()?'正在测试':'待测提交'}</span><b>01</b><small>示例提交 A</small></div><div><span>待处理</span><b>02</b><small>归档 / 草稿</small></div><div><span>等待队列</span><b>${String(c.state.queue.length).padStart(2,'0')}</b><small>FIFO</small></div><div><span>长期场景</span><b>04</b><small>3 approved · 1 draft</small></div></div>`;
  const nextAction = c => `<div class="v3-action-area">${c.running()?btn(c,'查看当前 Run','data-nav="active"',true):btn(c,'测试当前场景分支','data-open="request"',true)}${link('查看 Git 变化','git')}</div>`;
  const notice = c => c.stale() ? c.demoNotice() : `<p class="v3-demo">界面演示 · 所有提交、Run、时间和状态均为示意，不连接真实罗网实例。</p>`;
  const settingsChecks = c => ['Provider / 三角色','Playwright MCP','OSS Evidence','GitHub 综合','非生产环境'].map(x=>`<div class="v3-check"><span>${x}</span>${c.badge(c.state.checks[x]||'未检查',c.state.checks[x]?'warn':'neutral')}</div>`).join('');
  const settingsFocus = c => c.settingsTabs.find(t=>t[0]===c.state.settingTab)?.[1]||'模型服务';
  const settingsForm = c => c.state.settingTab==='checks' ? `<div class="v3-check-list">${settingsChecks(c)}</div><div class="section-space">${btn(c,'演示测试全部','data-check="all"',true)}</div><p class="muted small">未配置和未启用不能算通过；此处仅显示模拟反馈。</p>` : `<form class="v3-form" id="settings-demo-form" autocomplete="off">${c.settingFields()}${['transfer','security'].includes(c.state.settingTab)?'':`<div class="row wrap section-space">${btn(c,'模拟保存',`data-save="${c.state.settingTab}"`)}${btn(c,'模拟保存并测试',`data-check="${c.state.settingTab}"`,true)}</div>`}</form>`;
  const settingsNav = (c,kind='rail') => `<nav class="v3-config-nav ${kind}" aria-label="配置模块">${c.settingsTabs.map(([id,name],i)=>`<button type="button" data-setting="${id}" class="${id===c.state.settingTab?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${name}</button>`).join('')}</nav>`;
  const scenarioFilters = c => `<div class="v3-filters"><label class="field">查找场景<input id="scenario-query" value="${c.escape(c.state.scenarioQuery)}" placeholder="ID / 名称 / 标签" autocomplete="off"></label><label class="field">状态<select id="scenario-filter"><option value="all">全部状态</option><option value="approved">approved</option><option value="draft">draft</option><option value="deprecated">deprecated</option></select></label></div>`;
  const runFilters = c => `<div class="v3-filters"><label class="field">查找 Run<input id="run-query" value="${c.escape(c.state.runQuery)}" placeholder="Run ID / 标题 / target" autocomplete="off"></label><label class="field">结果<select id="run-filter"><option value="all">全部结果</option><option value="running">执行中</option><option value="passed">passed</option><option value="failed">failed</option><option value="blocked">blocked</option></select></label></div>`;
  const scenarioDetail = c => {const s=c.scenarios.find(x=>x.id===c.state.selectedScenario)||c.scenarios[0];return `<div class="v3-scenario-detail">${eyebrow('SELECTED / '+s.id)}<h2>${s.name}</h2>${c.badge(s.status,s.status==='approved'?'good':'warn')}<p>${s.purpose}</p><h3>步骤</h3><ol>${s.steps.map(x=>`<li>${x}</li>`).join('')}</ol><h3>期望</h3><p>${s.expectation}</p><small>历史：${s.history}</small></div>`};
  const scenarioPick = (c,s,text='阅读场景') => `<button class="link-button" data-scenario="${s.id}" type="button">${text} ↗</button>`;
  const runList = (c,klass='') => {const runs=ready(c).filteredRuns;return runs.length?`<div class="v3-run-list ${klass}">${runs.map((r,i)=>`<article class="v3-run"><span class="v3-index">${String(i+1).padStart(2,'0')}</span><div><h3>${c.escape(r.title)}</h3><span class="mono">${c.escape(r.id)}</span><small>${c.escape(r.trigger)} · ${c.escape(r.target)} · ${c.escape(r.archive)}</small></div>${c.runResult(r)}${openRun(r.id)}</article>`).join('')}</div>`:`<div class="empty">没有符合筛选条件的 Run。</div>`};
  const scenarioList = (c,klass='') => {const list=ready(c).scenarios;return list.length?`<div class="v3-scenario-list ${klass}">${list.map((s,i)=>`<article class="v3-scenario"><span class="v3-index">${String(i+1).padStart(2,'0')}</span><div><span class="mono">${s.id}</span><h3>${s.name}</h3><p>${s.purpose}</p><small>${s.tags.join(' / ')}</small></div>${c.badge(s.status,s.status==='approved'?'good':'warn')}${scenarioPick(c,s)}</article>`).join('')}</div>`:`<div class="empty">没有匹配场景，请清除筛选。</div>`};
  const repoFacts = c => `<div class="v3-repo-facts"><div><span>远端场景分支</span><b>scenario-testing</b></div><div><span>最新 HEAD</span><b>示例提交 A</b></div><div><span>上次已完成目标</span><b>示例提交 B</b></div><div><span>待测变化</span><b>1 个示意提交</b></div></div>`;
  const commits = c => `<div class="v3-commits"><div><span class="v3-index">A</span><strong>示例提交 A</strong><small>已进入场景测试分支 · 尚待测试</small></div><div><span class="v3-index">B</span><strong>示例提交 B</strong><small>DEMO-RUN-00 的已完成目标</small></div><div><span class="v3-index">C</span><strong>示例提交 C</strong><small>历史基线</small></div></div>`;
  const mergeForm = c => `<form id="merge-form" class="v3-merge-form"><label class="field">来源 branch / tag / SHA<input name="sourceRef" required maxlength="80" placeholder="例如 feature/demo" autocomplete="off"></label><label class="check"><input type="checkbox" name="initialization"> 场景分支首次创建时初始化</label><button class="btn primary" type="submit">模拟入队 merge-source</button><p class="muted tiny">只添加演示请求；不执行 merge、push 或创建 Run。</p></form>`;
  const dependencySummary = c => `<div class="v3-deps"><div><b>GitHub</b>${c.badge('正常','good')}</div><div><b>Provider / Pi</b>${c.badge(c.stale()?'陈旧':'正常',c.stale()?'warn':'good')}</div><div><b>Playwright / OSS</b>${c.badge(c.stale()?'需复核':'正常',c.stale()?'warn':'good')}</div></div>`;
  const activeEmpty = c => `<div class="v3-active-empty"><span class="micro">NO ACTIVE RUN</span><h2>现在没有正在执行的测试。</h2><p>回到总览看待测变更与最近结果；需要测试时通过人工请求进入 FIFO。</p><div class="row wrap">${btn(c,'发起演示测试','data-open="request"',true)}${link('查看最近 Runs','runs')}</div></div>`;
  const activeDetails = c => `<div class="v3-active-data"><div class="v3-progress"><strong>${c.progress()}</strong><span>场景已完成 / 总数</span><div class="progress"><i style="width:${c.state.stage===1?50:100}%"></i></div></div><div>${eyebrow('ACTIVE ROLE')}<h2>${c.current()}</h2><p>当前场景 AUTH-SESSION-DEMO · 固定 target 示例提交 A。</p>${btn(c,'推进演示阶段','data-next-stage')}</div></div>`;
  const stepLog = c => `<div class="v3-step-log">${['Main · 规划：选择 4 个场景并固定 target','Runner：执行 AUTH-SESSION-DEMO 并记录证据','Reviewer：独立阅读原始证据','Main · 最终汇总：形成正式报告'].map((x,i)=>`<div class="${i<c.state.stage?'done':i===c.state.stage?'current':''}"><span class="v3-index">0${i+1}</span><p>${x}</p><span>${i<c.state.stage?'已交接':i===c.state.stage?'当前':'待进行'}</span></div>`).join('')}</div>`;
  const artifactList = c => `<div class="v3-artifacts"><div><b>plan.md</b>${c.badge('已交接','good')}</div><div><b>execution.md</b>${c.badge(c.state.stage===1?'写入中':'示意已形成')}</div><div><b>review.md</b>${c.badge(c.state.stage>2?'示意已形成':'待审核')}</div><div><b>report.md</b>${c.badge('待最终汇总')}</div></div><p class="muted tiny">截图和 OSS 证据不在原型中伪造。</p>`;

  /* 01 — Orderly workspace. Every view is a task-oriented tool panel. */
  function style1(view,c){const d=ready(c);
    if(view==='dashboard')return wrapper(view,1,`${intro(c,'WORKSPACE / OVERVIEW','需要你关注的事','空闲也能完成判断：看待测变化、待处理任务和最近正式结果。',btn(c,'发起演示测试','data-open="request"',true))}${notice(c)}${activeSummary(c)}<div class="v3-one-hero"><div><span class="micro">NEXT TESTABLE COMMIT</span><h2>${d.active?'场景分支正在测试':'场景分支有新变化'}</h2><p>${d.active?'示例提交 A 已固定为当前 Run 的 target；最终结论仍待审核。':'示例提交 A 尚未成为已完成测试目标。当前没有正在执行的 Run。'}队列 ${d.queue.length} 项。</p>${nextAction(c)}</div><div class="v3-one-sha"><span>SCENARIO-TESTING</span><strong>${d.active?'A / RUN':'A → ?'}</strong><small>上次完成 B · ${d.active?'当前测试 A':'待测 A'}</small></div></div>${summaryFacts(c)}<div class="v3-one-columns"><section><div class="section-heading"><h2>待处理</h2>${link('查看 Git','git')}</div>${taskRows(c)}</section><aside><div class="section-heading"><h2>最近结果</h2>${link('所有 Runs','runs')}</div>${lastResult(c)}<div class="section-heading section-space-lg"><h2>最近活动</h2></div>${activityRows(c)}</aside></div><div class="v3-one-bottom"><section><h2>队列</h2>${queue(c)}</section><section><h2>依赖健康</h2>${dependencySummary(c)}</section></div>`);
    if(view==='active')return wrapper(view,1,`${intro(c,'WORKSPACE / LIVE','当前测试','有 Run 时查看场景、角色、工件和活动；空闲时保留明确入口。')}${notice(c)}${d.active?`${activeDetails(c)}<div class="v3-one-columns"><section><h2>交接与步骤</h2>${stepLog(c)}</section><aside><h2>已产生工件</h2>${artifactList(c)}${openRun('DEMO-RUN-01','打开 Run 详情')}</aside></div>`:`${activeEmpty(c)}<div class="v3-one-columns"><section><h2>最近已完成</h2>${lastResult(c)}</section><aside><h2>下一次测试</h2>${taskRows(c)}</aside></div>`}`);
    if(view==='runs')return wrapper(view,1,`${intro(c,'WORKSPACE / RUN STORE','运行记录','可按结果检索，打开工件与归档详情。')}${runFilters(c)}${runList(c,'table-like')}<div class="v3-one-bottom"><section><h2>归档待办</h2><p>DEMO-RUN-ARCHIVE 的结论已成立，归档仍需重试。</p>${openRun('DEMO-RUN-ARCHIVE','查看重试')}</section><section><h2>结果规则</h2><p>blocked 不推进；清理收尾失败单独告警。</p></section></div>`);
    if(view==='scenarios')return wrapper(view,1,`${intro(c,'WORKSPACE / SCENARIO LIBRARY','长期场景','场景正文只读自 Git 索引；单击条目阅读期望。')}${scenarioFilters(c)}<div class="v3-one-columns"><section>${scenarioList(c,'table-like')}</section><aside>${scenarioDetail(c)}</aside></div>`);
    if(view==='git')return wrapper(view,1,`${intro(c,'WORKSPACE / REPOSITORY','Git 与队列','单一场景测试分支；Run target 由调度时固定。',btn(c,'演示同步','data-sync'))}${repoFacts(c)}<div class="v3-one-columns"><section><h2>提交路径</h2>${commits(c)}<h2 class="section-space-lg">顺序队列</h2>${queue(c)}</section><aside><h2>合并来源</h2>${mergeForm(c)}<h2 class="section-space-lg">索引状态</h2>${dependencySummary(c)}</aside></div>`);
    return wrapper(view,1,`${intro(c,'WORKSPACE / SETTINGS','配置中心','按职责选择服务，模拟保存与检查；Secret 不进入原型。')}${notice(c)}<div class="v3-one-settings">${settingsNav(c)}<section class="v3-config-focus"><div class="section-heading"><div>${eyebrow('SELECTED MODULE')}<h2>${settingsFocus(c)}</h2></div>${c.badge('仅演示')}</div>${settingsForm(c)}</section><aside><h2>最近检查</h2>${settingsChecks(c)}<p class="muted small section-space">更新配置后需要重新检查，不复用旧通过状态。</p></aside></div>`);
  }

  /* 02 — Editorial periodical. Every screen reads as a separate article/chapter. */
  function style2(view,c){const d=ready(c);const folio=`<div class="v3-folio"><span>LUOWANG / TEST JOURNAL</span><span>示意资料 · 不代表实际运行</span></div>`;
    if(view==='dashboard')return wrapper(view,2,`${folio}<div class="v3-editorial-lead">${eyebrow('第 01 期 / 今日观察')}<h1>${d.active?'测试进行时，<br>结论尚未形成。':'测试暂停时，<br>事实仍在更新。'}</h1><p>首页不是进度条的容器。${d.active?'当前 Run 只显示摘要，执行步骤在详情中。':'下一次可测提交、上一次可信结果和未完成的归档，才是今天的头条。'}</p></div>${activeSummary(c)}<div class="v3-editorial-columns"><article><span class="v3-number">01</span><h2>${d.active?'一个提交，正在测试':'一个提交，等待测试'}</h2><p>场景测试分支已经包含示例提交 A。${d.active?'它已固定为当前 Run 的 target；Reviewer 尚未形成结论。':'上次已完成的目标是示例提交 B；这段变化尚未形成正式结论。'}</p>${nextAction(c)}<hr class="sep"><div class="section-heading"><h2>短讯 / 待处理</h2></div>${taskRows(c)}</article><aside><span class="v3-number">02</span><h2>上一份正式结果</h2>${lastResult(c)}<h2 class="section-space-lg">最近发生</h2>${activityRows(c)}<h2 class="section-space-lg">系统旁注</h2><p>队列 ${d.queue.length} 项 · 依赖状态见配置页。</p></aside></div>`);
    if(view==='active')return wrapper(view,2,`${folio}<div class="v3-editorial-lead">${eyebrow('第 02 章 / 执行现场')}<h1>${d.active?'一次测试，四次交接。':'此刻，测试处于空闲。'}</h1><p>${d.active?'详情页从计划、执行到审核，记录每个阶段的可核验事实。':'没有活跃 Run 时，阅读近期结果或发起新请求，比展示空进度更有意义。'}</p></div><div class="v3-editorial-columns"><article>${d.active?`${activeDetails(c)}<h2>执行手记</h2>${stepLog(c)}`:activeEmpty(c)}</article><aside>${eyebrow('ANNOTATIONS')}<h2>文档与注释</h2>${d.active?artifactList(c):lastResult(c)}<hr class="sep"><p class="muted small">Runner 观察是待审假设；正式结论以 Reviewer 审核为依据。</p></aside></div>`);
    if(view==='runs')return wrapper(view,2,`${folio}<div class="v3-editorial-lead">${eyebrow('第 03 章 / 历史台账')}<h1>结果的来路，<br>比结果本身更重要。</h1><p>每条 Run 固定 target；归档失败和测试结论分别记录。</p></div><div class="v3-editorial-columns"><article>${runFilters(c)}${runList(c,'editorial')}</article><aside><span class="v3-number">${String(d.filteredRuns.length).padStart(2,'0')}</span><h2>本页记录</h2><p>从运行记录可以进入摘要、计划、执行、审核、报告与证据栏目。</p>${link('查看场景期望','scenarios')}</aside></div>`);
    if(view==='scenarios')return wrapper(view,2,`${folio}<div class="v3-editorial-lead">${eyebrow('第 04 章 / 场景目录')}<h1>长期场景，<br>是可读的业务约定。</h1><p>状态与标签用于检索，不构成手工测试套件。</p></div>${scenarioFilters(c)}<div class="v3-editorial-columns"><article>${scenarioList(c,'editorial')}</article><aside>${scenarioDetail(c)}</aside></div>`);
    if(view==='git')return wrapper(view,2,`${folio}<div class="v3-editorial-lead">${eyebrow('第 05 章 / 版本事实')}<h1>一个分支，<br>一条可回溯的历史。</h1><p>只有纳入 scenario-testing 的提交，才进入正式测试事实。</p></div><div class="v3-editorial-columns"><article><h2>版本纪事</h2>${commits(c)}<h2>人工来源</h2>${mergeForm(c)}</article><aside><h2>版本注释</h2>${repoFacts(c)}<h2>等待队列</h2>${queue(c)}</aside></div>`);
    return wrapper(view,2,`${folio}<div class="v3-editorial-lead">${eyebrow('第 06 章 / 配置档案')}<h1>逐项配置，<br>逐项验证。</h1><p>模型、证据、仓库与环境各有职责；一次演示检查不是连接成功的证明。</p></div><div class="v3-editorial-columns"><article>${eyebrow('CURRENT CHAPTER / '+settingsFocus(c))}<h2>${settingsFocus(c)}</h2>${settingsForm(c)}</article><aside><h2>本册目录</h2>${settingsNav(c,'editorial')}<h2 class="section-space-lg">检查附录</h2>${settingsChecks(c)}</aside></div>`);
  }

  /* 03 — Signal wall. Dense operational readouts on dark spruce, never black/purple. */
  function style3(view,c){const d=ready(c);const band=(title,detail) => `<div class="v3-signal-band"><span>${title}</span><strong>${detail}</strong><span>SCENARIO TESTING / DEMO</span></div>`;
    if(view==='dashboard')return wrapper(view,3,`${band('SYSTEM 01 / OVERVIEW',d.active?'RUNNING / IN REVIEW':'IDLE / READY')}<div class="v3-signal-head"><div>${eyebrow('DECISION SURFACE')}<h1>${d.active?'CURRENT RUN / SUMMARY':'现在不用盯进度。'}</h1><p>看待测变化、归档异常和最近结论；运行时再进入详情。</p></div><div class="v3-signal-head-state"><b>${d.active?'RUNNING':'IDLE'}</b><span>QUEUE ${String(d.queue.length).padStart(2,'0')} · PENDING 01</span></div></div>${activeSummary(c)}<div class="v3-signal-metrics">${summaryFacts(c)}</div><div class="v3-signal-grid"><section class="v3-signal-priority"><span>01 / PRIORITY</span><h2>${d.active?'当前目标':'待测提交'}<br>示例提交 A</h2><p>${d.active?'当前 Run 已固定目标 A，完整执行过程请进入详情。':'上次完成目标 B；当前分支 A 尚无对应正式 Run。'}</p>${nextAction(c)}</section><section><div class="section-heading"><h2>ACTION QUEUE</h2><span>03 ITEMS</span></div>${taskRows(c)}</section><section><h2>LAST VERIFIED</h2>${lastResult(c)}<h2>RECENT ACTIVITY</h2>${activityRows(c)}</section></div><div class="v3-signal-footer"><section><h2>QUEUE</h2>${queue(c)}</section><section><h2>DEPENDENCIES</h2>${dependencySummary(c)}</section></div>`);
    if(view==='active')return wrapper(view,3,`${band('SYSTEM 02 / ACTIVE',d.active?'RUNNING':'NO ACTIVE RUN')}<div class="v3-signal-head"><div>${eyebrow('SESSION MONITOR')}<h1>${d.active?'EXECUTION':'NO ACTIVE RUN'}</h1><p>场景步骤只在此处展示，不占用总览的信息焦点。</p></div>${d.active?`<b class="v3-dial">${c.progress()}</b>`:''}</div>${d.active?`<div class="v3-signal-grid"><section class="v3-signal-priority">${activeDetails(c)}</section><section><h2>HANDOFF LOG</h2>${stepLog(c)}</section><section><h2>ARTIFACTS</h2>${artifactList(c)}</section></div>`:`<div class="v3-signal-grid"><section class="v3-signal-priority">${activeEmpty(c)}</section><section><h2>LAST VERIFIED</h2>${lastResult(c)}</section><section><h2>NEXT ACTION</h2>${taskRows(c)}</section></div>`}`);
    if(view==='runs')return wrapper(view,3,`${band('SYSTEM 03 / RUN STORE',`${d.filteredRuns.length} RECORDS`)}<div class="v3-signal-head"><div>${eyebrow('RESULT MONITOR')}<h1>RUNS / ARCHIVE</h1><p>状态、固定提交、归档事实分列扫描。</p></div></div>${runFilters(c)}${runList(c,'signal')}<div class="v3-signal-footer"><section><h2>BLOCKED</h2><p>阻塞不会推进上次已完成目标。</p></section><section><h2>ARCHIVE ERROR</h2>${openRun('DEMO-RUN-ARCHIVE','查看重试')}</section></div>`);
    if(view==='scenarios')return wrapper(view,3,`${band('SYSTEM 04 / SCENARIOS',`${d.scenarios.length} MATCHES`)}<div class="v3-signal-head"><div>${eyebrow('INDEXED LIBRARY')}<h1>SCENARIO REGISTRY</h1><p>Git 中的长期场景只读索引。</p></div></div>${scenarioFilters(c)}<div class="v3-signal-two"><section>${scenarioList(c,'signal')}</section><aside>${scenarioDetail(c)}</aside></div>`);
    if(view==='git')return wrapper(view,3,`${band('SYSTEM 05 / REPOSITORY','SCENARIO-TESTING')}<div class="v3-signal-head"><div>${eyebrow('FIXED TARGET CONTROL')}<h1>GIT / QUEUE</h1><p>HEAD 是分支事实；Run target 必须是已发布的不可变提交。</p></div>${btn(c,'演示同步','data-sync')}</div><div class="v3-signal-metrics">${repoFacts(c)}</div><div class="v3-signal-grid"><section class="v3-signal-priority"><h2>COMMIT PATH</h2>${commits(c)}</section><section><h2>REQUEST FIFO</h2>${queue(c)}</section><section><h2>MERGE SOURCE</h2>${mergeForm(c)}</section></div>`);
    return wrapper(view,3,`${band('SYSTEM 06 / CONFIG',settingsFocus(c).toUpperCase())}<div class="v3-signal-head"><div>${eyebrow('DEPENDENCY CONTROL')}<h1>CONFIG / CHECKS</h1><p>配置与验证分开；模拟反馈绝非连接成功。</p></div>${c.badge('DEMO ONLY','warn')}</div>${settingsNav(c,'signal')}<div class="v3-signal-two"><section class="v3-signal-config"><h2>${settingsFocus(c)} / 控制项</h2>${settingsForm(c)}</section><aside><h2>CHECK READOUT</h2>${settingsChecks(c)}<h2>SECURITY</h2><p>Secret 字段不可输入；正式环境仅经 Secret Store。</p></aside></div>`);
  }

  /* 04 — Collaboration canvas. Spatial lanes, human-scale cards, no terminal cosplay. */
  function style4(view,c){const d=ready(c);const chapter=(n,title,desc)=>`<div class="v3-canvas-head">${eyebrow('CANVAS / '+n)}<h1>${title}</h1><p>${desc}</p></div>`;
    if(view==='dashboard')return wrapper(view,4,`${chapter('01','今天，先看这些。','空闲时任务板不会空白：待测提交、归档与场景维护各有位置。')}${activeSummary(c)}<div class="v3-canvas-columns"><section class="v3-canvas-lane"><div class="between"><h2>要处理 <span>01</span></h2>${c.badge('优先')}</div><div class="v3-canvas-ticket featured"><h3>${d.active?'执行示例提交 A':'测试示例提交 A'}</h3><p>${d.active?'当前 Run 已固定目标；详情页查看步骤与工件。':'在场景测试分支上固定目标，发起下一次 Run。'}</p>${nextAction(c)}</div>${tasks(c).slice(1).map(([n,title,desc,attr,verb])=>`<div class="v3-canvas-ticket"><small>ITEM ${n}</small><h3>${title}</h3><p>${desc}</p><button class="link-button" ${attr}>${verb} ↗</button></div>`).join('')}</section><section class="v3-canvas-lane"><div class="between"><h2>刚完成 <span>01</span></h2>${c.badge('passed','good')}</div><div class="v3-canvas-ticket">${lastResult(c)}</div><h2>最近活动</h2>${activityRows(c)}</section><section class="v3-canvas-lane"><div class="between"><h2>等待中 <span>${d.queue.length}</span></h2>${c.badge('FIFO')}</div>${queue(c)}<div class="v3-canvas-ticket">${dependencySummary(c)}</div></section></div>`);
    if(view==='active')return wrapper(view,4,`${chapter('02','执行中的协作。','进入当前测试才展开每一步交接；空闲时保留入口与历史。')}${d.active?`${activeDetails(c)}<div class="v3-canvas-columns handoff">${c.stages.map((s,i)=>`<section class="v3-canvas-lane"><h2>0${i+1} ${s}</h2><div class="v3-canvas-ticket">${c.badge(i<c.state.stage?'已交接':i===c.state.stage?'当前':'待进行',i<c.state.stage?'good':'')}<p>${['理解变化，固定计划','顺序执行场景并登记证据','独立读取证据并审核','根据审核形成报告'][i]}</p><strong>${['plan.md','execution.md','review.md','report.md'][i]}</strong></div></section>`).join('')}</div><div class="section-space-lg">${artifactList(c)}</div>`:`<div class="v3-canvas-columns"><section class="v3-canvas-lane">${activeEmpty(c)}</section><section class="v3-canvas-lane"><h2>最近完成</h2>${lastResult(c)}</section><section class="v3-canvas-lane"><h2>下一步</h2>${taskRows(c)}</section></div>`}`);
    if(view==='runs')return wrapper(view,4,`${chapter('03','每个结果，各有去处。','按结果分列，打开详情查看固定 target 和工件。')}${runFilters(c)}<div class="v3-canvas-columns">${[['running','正在执行'],['passed','已通过'],['blocked','受阻']].map(([kind,name])=>`<section class="v3-canvas-lane"><h2>${name} <span>${d.filteredRuns.filter(r=>r.result===kind).length}</span></h2>${d.filteredRuns.filter(r=>r.result===kind).map(r=>`<div class="v3-canvas-ticket"><small>${r.id}</small><h3>${r.title}</h3><p>${r.target} · ${r.archive}</p>${openRun(r.id)}</div>`).join('')||'<p class="muted small">暂无此类 Run</p>'}</section>`).join('')}</div>`);
    if(view==='scenarios')return wrapper(view,4,`${chapter('04','把场景摆上桌面。','标签是检索线索，卡片仍只读自 Git。')}${scenarioFilters(c)}<div class="v3-canvas-columns"><section class="v3-canvas-lane"><h2>核心 / approved</h2>${d.scenarios.filter(s=>s.status==='approved').map(s=>`<div class="v3-canvas-ticket"><small>${s.id}</small><h3>${s.name}</h3><p>${s.purpose}</p>${scenarioPick(c,s)}</div>`).join('')||'<p>没有匹配项</p>'}</section><section class="v3-canvas-lane"><h2>待确认 / draft</h2>${d.scenarios.filter(s=>s.status!=='approved').map(s=>`<div class="v3-canvas-ticket"><small>${s.id}</small><h3>${s.name}</h3><p>${s.purpose}</p>${scenarioPick(c,s)}</div>`).join('')||'<p>没有匹配项</p>'}</section><section class="v3-canvas-lane"><h2>选中场景</h2>${scenarioDetail(c)}</section></div>`);
    if(view==='git')return wrapper(view,4,`${chapter('05','版本变化进入队列。','先把来源安全纳入场景分支，再以固定 target 创建 Run。')}${repoFacts(c)}<div class="v3-canvas-columns"><section class="v3-canvas-lane"><h2>来源</h2><div class="v3-canvas-ticket">${mergeForm(c)}</div></section><section class="v3-canvas-lane"><h2>已纳入</h2>${commits(c)}</section><section class="v3-canvas-lane"><h2>待执行</h2>${queue(c)}</section></div>`);
    return wrapper(view,4,`${chapter('06','配置，也要有清晰进度。','每个服务是独立步骤；保存后才应进行真实检查。')}${settingsNav(c,'canvas')}<div class="v3-canvas-columns config"><section class="v3-canvas-lane"><h2>当前步骤 · ${settingsFocus(c)}</h2><div class="v3-canvas-ticket">${settingsForm(c)}</div></section><section class="v3-canvas-lane"><h2>连接检查</h2>${settingsChecks(c)}</section><section class="v3-canvas-lane"><h2>安全与边界</h2><div class="v3-canvas-ticket"><h3>Secret 不回显</h3><p>本演示不输入凭据；正式产品使用 Secret Store。</p></div><div class="v3-canvas-ticket"><h3>先保存，后检查</h3><p>配置变化使旧检查状态失效，不能继续显示旧成功。</p></div></section></div>`);
  }

  /* 05 — System map. Relations and nodes on a saturated engineering canvas. */
  function style5(view,c){const d=ready(c);const graphHead=(n,title,desc)=>`<header class="v3-map-head"><span>MAP / ${n}</span><h1>${title}</h1><p>${desc}</p></header>`;
    if(view==='dashboard')return wrapper(view,5,`${graphHead('01','系统在等待什么？','中心不是“当前进度”，而是可测提交与它的后续去向。')}${activeSummary(c)}<div class="v3-map-network"><div class="v3-map-node source"><span>LAST COMPLETED</span><b>示例提交 B</b><small>DEMO-RUN-00 · passed</small></div><div class="v3-map-connector">→</div><div class="v3-map-node focus"><span>TESTABLE HEAD</span><b>示例提交 A</b><small>${d.active?'DEMO-RUN-01 运行中':'等待发起测试'}</small>${btn(c,'模拟发起测试','data-open="request"',true)}</div><div class="v3-map-connector">→</div><div class="v3-map-node target"><span>FUTURE RUN</span><b>${d.active?'审核未完成':'尚未固定'}</b><small>${d.active?'等待 Reviewer':'调度时才固定 target'}</small></div></div><div class="v3-map-lower"><section><h2>待处理节点 / 03</h2>${taskRows(c)}</section><section><h2>最近事实</h2>${lastResult(c)}${activityRows(c)}</section><section><h2>队列和依赖</h2>${queue(c)}${dependencySummary(c)}</section></div>`);
    if(view==='active')return wrapper(view,5,`${graphHead('02','执行链路','只有执行详情展开场景进度、角色交接与工件。')}${d.active?`<div class="v3-map-network active">${c.stages.map((s,i)=>`<div class="v3-map-node ${i===c.state.stage?'focus':i<c.state.stage?'source':'target'}"><span>SESSION 0${i+1}</span><b>${s}</b><small>${i===c.state.stage?c.progress():i<c.state.stage?'已交接':'未开始'}</small></div>`).join('<div class="v3-map-connector">→</div>')}</div><div class="v3-map-lower"><section>${activeDetails(c)}</section><section><h2>步骤轨迹</h2>${stepLog(c)}</section><section><h2>工件关系</h2>${artifactList(c)}</section></div>`:`<div class="v3-map-network"><div class="v3-map-node focus">${activeEmpty(c)}</div><div class="v3-map-node target">${lastResult(c)}</div></div>`}`);
    if(view==='runs')return wrapper(view,5,`${graphHead('03','Run / target 矩阵','每条结果落到固定提交上，归档是单独的事实。')}${runFilters(c)}<div class="v3-map-run-grid"><div class="axis">RUN ID</div><div class="axis">TARGET</div><div class="axis">RESULT</div><div class="axis">ARCHIVE</div>${d.filteredRuns.map(r=>`<div>${openRun(r.id,r.id)}</div><div>${r.target}</div><div>${c.runResult(r)}</div><div>${r.archive}</div>`).join('')||'<p class="empty">没有匹配记录。</p>'}</div><div class="v3-map-lower"><section><h2>不推进</h2><p>blocked 不更新已完成目标。</p></section><section><h2>重试点</h2>${openRun('DEMO-RUN-ARCHIVE','归档失败 Run')}</section></div>`);
    if(view==='scenarios')return wrapper(view,5,`${graphHead('04','场景 / 标签拓扑','平铺场景文件，通过标签和状态建立关联，而不是维护 suite。')}${scenarioFilters(c)}<div class="v3-map-lower"><section><h2>CORE / ${d.scenarios.filter(s=>s.tags.includes('core')).length}</h2>${d.scenarios.filter(s=>s.tags.includes('core')).map(s=>`<div class="v3-map-item"><strong>${s.id}</strong><span>${s.name}</span>${scenarioPick(c,s)}</div>`).join('')}</section><section><h2>OTHER / ${d.scenarios.filter(s=>!s.tags.includes('core')).length}</h2>${d.scenarios.filter(s=>!s.tags.includes('core')).map(s=>`<div class="v3-map-item"><strong>${s.id}</strong><span>${s.name}</span>${scenarioPick(c,s)}</div>`).join('')||'<p>无匹配项</p>'}</section><section>${scenarioDetail(c)}</section></div>`);
    if(view==='git')return wrapper(view,5,`${graphHead('05','固定提交的路径','从来源 ref 经场景测试分支，成为一个 Run 的不可变目标。')}${repoFacts(c)}<div class="v3-map-network"><div class="v3-map-node source"><span>SOURCE REF</span><b>branch / tag / SHA</b><small>请求入队前解析</small></div><div class="v3-map-connector">→</div><div class="v3-map-node focus"><span>SCENARIO BRANCH</span><b>scenario-testing</b><small>prepared / resolved</small></div><div class="v3-map-connector">→</div><div class="v3-map-node target"><span>RUN TARGET</span><b>不可变 SHA</b><small>只测已发布提交</small></div></div><div class="v3-map-lower"><section><h2>提交层</h2>${commits(c)}</section><section><h2>排队层</h2>${queue(c)}</section><section><h2>来源输入</h2>${mergeForm(c)}</section></div>`);
    return wrapper(view,5,`${graphHead('06','依赖配置网络','先在网络中选节点，再在右侧处理当前模块。')}${settingsNav(c,'map')}<div class="v3-map-lower config"><section><h2>当前节点</h2><div class="v3-map-node focus"><span>SELECTED CONFIG</span><b>${settingsFocus(c)}</b><small>仅演示 · 未保存</small></div><div class="v3-map-node target"><span>ROLE LIMIT</span><b>Secret Store</b><small>无明文回显</small></div></section><section class="v3-map-form"><h2>${settingsFocus(c)} / 参数</h2>${settingsForm(c)}</section><section><h2>连通性边</h2>${settingsChecks(c)}</section></div>`);
  }

  /* 06 — Run notebook. Narrative, dated entries and annotated field notes. */
  function style6(view,c){const d=ready(c);const cover=(chapter,title,desc)=>`<div class="v3-notebook-cover"><div><span>FIELD BOOK / ${chapter}</span><h1>${title}</h1><p>${desc}</p></div><b>${chapter}</b></div>`;
    if(view==='dashboard')return wrapper(view,6,`${cover('01',d.active?'有运行，也有待处理。':'没有运行，也有工作要做。','首页记录待测变化、最近可信结果与后续动作；运行中只出现一行当前 Run 摘要。')}${activeSummary(c)}<div class="v3-notebook-columns"><article><h2>今日记录</h2><div class="v3-notebook-entry"><span>待测</span><div><h3>${d.active?'正在验证示例提交 A':'场景测试分支有新提交'}</h3><p>${d.active?'当前 Run 目标已固定，尚未形成最终结论。':'示例提交 A 尚未形成已完成测试结果。'}上一份报告对应提交 B。</p>${nextAction(c)}</div></div><div class="v3-notebook-entry"><span>最近结果</span><div>${lastResult(c)}</div></div><h2>活动摘记</h2>${activityRows(c)}</article><aside><h2>待办清单</h2>${taskRows(c)}<h2>队列边栏</h2>${queue(c)}<p class="muted small">${d.queue.length===0?'当前空闲；无待执行请求。':'新请求已进入演示队列。'}</p></aside></div>`);
    if(view==='active')return wrapper(view,6,`${cover('02',d.active?'此刻正在发生的事。':'这一页暂时没有新记录。','打开执行详情，按交接顺序阅读步骤与工件。')}${d.active?`<div class="v3-notebook-columns"><article><h2>执行日记</h2>${activeDetails(c)}${stepLog(c)}</article><aside><h2>旁注 / 工件</h2>${artifactList(c)}${openRun('DEMO-RUN-01','Run 详情')}</aside></div>`:`<div class="v3-notebook-columns"><article>${activeEmpty(c)}<h2>上一条完成记录</h2>${lastResult(c)}</article><aside><h2>可继续阅读</h2>${taskRows(c)}</aside></div>`}`);
    if(view==='runs')return wrapper(view,6,`${cover('03','每次运行，留下自己的页码。','从最近到过去阅读 Run，不把归档状态与测试结果混为一谈。')}${runFilters(c)}<div class="v3-notebook-columns"><article>${runList(c,'notebook')}</article><aside><h2>索引注</h2><p>点击任一 Run 查看计划、执行、审核、报告与证据栏目。</p><p class="section-space">正式报告在 Git；详细活动在 Run Store。</p></aside></div>`);
    if(view==='scenarios')return wrapper(view,6,`${cover('04','场景不是一次性的清单。','业务期望通过长期 Markdown 场景留在目标仓库。')}${scenarioFilters(c)}<div class="v3-notebook-columns"><article>${scenarioList(c,'notebook')}</article><aside><h2>当前页</h2>${scenarioDetail(c)}</aside></div>`);
    if(view==='git')return wrapper(view,6,`${cover('05','提交沿着一条时间线前进。','只有进入场景测试分支的不可变提交才成为正式 Run target。')}${repoFacts(c)}<div class="v3-notebook-columns"><article><h2>版本纪事</h2>${commits(c)}<h2>人工来源请求</h2>${mergeForm(c)}</article><aside><h2>队列页</h2>${queue(c)}<h2>同步注记</h2><p>Git 暂不可达时，旧索引必须明确标记陈旧。</p>${btn(c,'模拟同步反馈','data-sync')}</aside></div>`);
    return wrapper(view,6,`${cover('06','配置从来不是一张长表。','像手账目录一样按章节组织外部依赖，每次只处理一组职责。')}<div class="v3-notebook-columns"><article><div class="v3-notebook-chapter">${eyebrow('CHAPTER / '+c.state.settingTab.toUpperCase())}<h2>${settingsFocus(c)}</h2><p class="muted small">当前章节的字段和演示反馈。</p>${settingsForm(c)}</div></article><aside><h2>章节目录</h2>${settingsNav(c,'notebook')}<h2>检查摘录</h2>${settingsChecks(c)}</aside></div>`);
  }

  return {render(style,view,c){const fn=[style1,style2,style3,style4,style5,style6][style-1];return fn(view,c)}};
})();
